result.output:
  }

  if (industryTagId && assetTagId) {
    possibleCombos.push(`${industryTagId}_${assetTagId}`);
  }

  if (productTagId && industryTagId && assetTagId) {
    possibleCombos.push(`${productTagId}_${industryTagId}_${assetTagId}`);
  }

