}

function _getCombosToScores(tagQuantData) {
  const pulseIdToScores = {};
  const pulseIdToTags = {};
  tagQuantData.forEach((tagData) => {
    const { pulseId, scores, createdAt } = tagData;
    pulseIdToScores[pulseId] = { scores, createdAt };

    if (!pulseIdToTags?.[pulseId]) {
      pulseIdToTags[pulseId] = {};
    }

    pulseIdToTags[pulseId][tagData.tagType] = tagData.tagId;
  });

  const combosToScores = {};
  Object.entries(pulseIdToTags).forEach(([pulseId, tags]) => {
    const possibleCombos = getCombos(tags);

    possibleCombos.forEach((combo) => {
      if (!combosToScores[combo]) {
        combosToScores[combo] = [];
      }

      combosToScores[combo].push(pulseIdToScores[pulseId]);
    });
  });

  return combosToScores;
}

async function getSelectableTags({ requestedTagIds = [], originalTagIds = [], transaction = null } = {}) {
  const tags = await listAllPulseTags({ transaction });

  const tagIdToTag = {};
  tags.forEach((tag) => {
    tagIdToTag[tag.id] = tag;
  });

  const tagTypeToIds = {};
  tags.forEach((tag) => {
    if (!tagTypeToIds[tag.type]) {
      tagTypeToIds[tag.type] = [];
    }

    tagTypeToIds[tag.type].push(tag.id);
  });

  const tagTypeToTags = {};
  tags.forEach((tag) => {
    if (!tagTypeToTags[tag.type]) {
      tagTypeToTags[tag.type] = [];
    }

    tagTypeToTags[tag.type].push(tag);
  });

  const requestedTags = tags.filter((tag) => requestedTagIds.includes(tag.id));

  const tagTypeToRequestedTag = {};
  requestedTags.forEach((tag) => {
    tagTypeToRequestedTag[tag.type] = tag;
  });

  const requestedProductTag = requestedTags.find((tag) => tag.type === PulseTagType.Product);
  const requestedIndustryTag = requestedTags.find((tag) => tag.type === PulseTagType.Industry);
  const requestedAssetTag = requestedTags.find((tag) => tag.type === PulseTagType.Asset);

  const combosToScores = await getCombosToScores({ transaction });

  const requestedTagIdsByType = {};
  requestedTags.forEach((tag) => {
    requestedTagIdsByType[tag.type] = tag.id;
  });
  const requestedSelectionIsSelectable = hasSelectableRequestedBenchmark(
    requestedTagIdsByType,
    combosToScores
  );

  // Requested tags remain selected, but are selectable only when the selection can produce a benchmark.
  requestedTags.forEach((tag) => {
    tag.isSelected = true;
    tag.isSelectable = requestedSelectionIsSelectable;
  });

  // If a tag's type is requested, then only that tag is 'selected'. That tag may also be 'recommended', but not
  // necessarily. And other tags of this type tags may be selectable, given that selecting such a tag would unselect
  // the currently requested tag.
  Object.entries(tagTypeToRequestedTag).forEach(([tagType, requestedTag]) => {
    tagTypeToTags[tagType].forEach((tag) => {
      if (tag.id !== requestedTag.id) {
        tag.isSelected = false;
      }
      const isRecommended = originalTagIds.includes(tag.id);
      tag.isRecommended = isRecommended;
    });
  });

  // Otherwise, find the search combos and see which ones result in useful data.
  const searchCombos = _makeSearchCombos(
    requestedProductTag,
    requestedIndustryTag,
    requestedAssetTag,
    tagTypeToIds
  );

  searchCombos.forEach((combo) => {
    const scores = combosToScores[combo];
    const tagIds = combo.split('_');
    const nonRequestedTagIds = tagIds.filter((tagId) => !requestedTagIds.includes(tagId));

    const isSelectable = hasCompleteBenchmarkPopulation(scores);

    nonRequestedTagIds.forEach((tagId) => {
      const tag = tagIdToTag[tagId];
      tag.isSelected = false;
      tag.isSelectable = isSelectable;

      const isRecommended = originalTagIds.includes(tagId);
      tag.isRecommended = isRecommended;
    });
  });

  return tagTypeToTags;
}

/**
 * Finds all possible search combos given the requested tags.
 *
 * Note: by "search combos" this means combinations of tags that should be checked to see whether or not they have
 * enough scores to be useful. This is necessary in order to determine which tags are selectable and which are not
 * in the frontend.
 *
 * If you were to request some set of tag types, then you would want to check all possible combinations that include
 * those types, BUT ALSO the combinations that exist when you drop one of those types. This is because when you select
 * a tag you are indicating that you are not selected another tag of the same type. HOWEVER, if you were to switch to
 * another tag selection of the same type, that action would unselect the previously selected tag. Thus, we need to
 * know exactly which tags are selectable given the current requested selection, but also what tags would be selectable
 * if you were to change your selection.
 *
 * Example: you provide tags for product and industry. You need to determine which asset tags are selectable. Therefore
 * you need to find all possible assets that are part of the combination product+industry+asset. You also need to
 * determine which products may be selectable given your selected industry, and which industries may be selectable given
 * your selected product. So the search combos are:
 * - product_industry_<all assets>
 * - product_<all industries>
 * - <all_products>_industry
 *
 * @param {String} requestedProductTag requested product tag id
 * @param {String} requestedIndustryTag requested industry tag id
 * @param {String} requestedAssetTag requested asset tag id
 * @param {Object} tagTypeToIds Map of tag type to the ids of tags of that type
 *
 * @returns Array<String> possible search combos
 */
function _makeSearchCombos(requestedProductTag, requestedIndustryTag, requestedAssetTag, tagTypeToIds) {
  const productTagId = requestedProductTag?.id;
  const industryTagId = requestedIndustryTag?.id;
  const assetTagId = requestedAssetTag?.id;

  // If all three tags are present, consider the search combos where any one of the three is missing.
  if (productTagId && industryTagId && assetTagId) {
    const assetSearchCombos = tagTypeToIds[PulseTagType.Asset].map(
      (assetId) => `${productTagId}_${industryTagId}_${assetId}`
    );
    const industrySearchCombos = tagTypeToIds[PulseTagType.Industry].map(
      (industryId) => `${productTagId}_${industryId}_${assetTagId}`
    );
    const productSearchCombos = tagTypeToIds[PulseTagType.Product].map(
      (productId) => `${productId}_${industryTagId}_${assetTagId}`
    );
    return [...assetSearchCombos, ...industrySearchCombos, ...productSearchCombos];
  }

  // Missing asset.
  if (productTagId && industryTagId && !assetTagId) {
    const assetSearchCombos = tagTypeToIds[PulseTagType.Asset].map(
      (assetId) => `${productTagId}_${industryTagId}_${assetId}`
    );
    const industrySearchCombos = tagTypeToIds[PulseTagType.Industry].map(
      (industryId) => `${productTagId}_${industryId}`
    );
    const productSearchCombos = tagTypeToIds[PulseTagType.Product].map(
      (productId) => `${productId}_${industryTagId}`
    );
    return [...assetSearchCombos, ...industrySearchCombos, ...productSearchCombos];
  }

  // Missing industry.
  if (productTagId && !industryTagId && assetTagId) {
    const industrySearchCombos = tagTypeToIds[PulseTagType.Industry].map(
      (industryId) => `${productTagId}_${industryId}_${assetTagId}`
    );
    const productSearchCombos = tagTypeToIds[PulseTagType.Product].map(
      (productId) => `${productId}_${assetTagId}`
    );
    const assetSearchCombos = tagTypeToIds[PulseTagType.Asset].map((assetId) => `${productTagId}_${assetId}`);
    return [...industrySearchCombos, ...productSearchCombos, ...assetSearchCombos];
  }

  // Missing product.
  if (!productTagId && industryTagId && assetTagId) {
    const productSearchCombos = tagTypeToIds[PulseTagType.Product].map(
      (productId) => `${productId}_${industryTagId}_${assetTagId}`
    );
    const industrySearchCombos = tagTypeToIds[PulseTagType.Industry].map(
      (industryId) => `${industryId}_${assetTagId}`
    );
    const assetSearchCombos = tagTypeToIds[PulseTagType.Asset].map((assetId) => `${industryTagId}_${assetId}`);
    return [...productSearchCombos, ...industrySearchCombos, ...assetSearchCombos];
  }

  // Missing industry and asset.
  if (productTagId && !industryTagId && !assetTagId) {
    const assetSearchCombos = tagTypeToIds[PulseTagType.Asset].map((assetId) => `${productTagId}_${assetId}`);
    const industrySearchCombos = tagTypeToIds[PulseTagType.Industry].map(
      (industryId) => `${productTagId}_${industryId}`
    );
    const productSearchCombos = tagTypeToIds[PulseTagType.Product].map((productId) => `${productId}`);
    return [...assetSearchCombos, ...industrySearchCombos, ...productSearchCombos];
  }

  // Missing product and asset.
  if (!productTagId && industryTagId && !assetTagId) {
    const assetSearchCombos = tagTypeToIds[PulseTagType.Asset].map((assetId) => `${industryTagId}_${assetId}`);
    const productSearchCombos = tagTypeToIds[PulseTagType.Product].map(
      (productId) => `${productId}_${industryTagId}`
    );
    const industrySearchCombos = tagTypeToIds[PulseTagType.Industry].map((industryId) => `${industryId}`);
    return [...assetSearchCombos, ...productSearchCombos, ...industrySearchCombos];
  }

  // Missing product and industry.
  if (!productTagId && !industryTagId && assetTagId) {
    const industrySearchCombos = tagTypeToIds[PulseTagType.Industry].map(
      (industryId) => `${industryId}_${assetTagId}`
    );
    const productSearchCombos = tagTypeToIds[PulseTagType.Product].map(
      (productId) => `${productId}_${assetTagId}`
    );
    const assetSearchCombos = tagTypeToIds[PulseTagType.Asset].map((assetId) => `${assetId}`);
    return [...industrySearchCombos, ...productSearchCombos, ...assetSearchCombos];
  }

  // Missing product, industry, and asset. (default case)
  if (!productTagId && !industryTagId && !assetTagId) {
    const assetSearchCombos = (tagTypeToIds?.[PulseTagType.Asset] ?? []).map((assetId) => `${assetId}`);
    const industrySearchCombos = (tagTypeToIds?.[PulseTagType.Industry] ?? []).map(
      (industryId) => `${industryId}`
    );
    const productSearchCombos = (tagTypeToIds?.[PulseTagType.Product] ?? []).map(
      (productId) => `${productId}`
    );
    return [...assetSearchCombos, ...industrySearchCombos, ...productSearchCombos];
  }
}

async function cacheTagQuantData({ shouldUpdate = true, forceUpdate = false, transaction = null } = {}) {
  if (
    !forceUpdate &&
    cachedTagDataLastUpdated &&
    !_.isEmpty(cachedCombosToScores) &&
    !_.isEmpty(cachedPulseTags)
  ) {
    const isExpired = moment(cachedTagDataLastUpdated).add(REFRESH_LENGTH, REFRESH_UNIT).isBefore(moment());
    // Only return the cached data if it exists and is not expired (unless we should not update)
    if (!isExpired || !shouldUpdate) {
      return;
    }
  }

  const refreshComboData = async (transaction) => {
    const tagQuantData = await _getTagQuantData({ transaction });
    cachedCombosToScores = _getCombosToScores(tagQuantData);
    logger.info(`Cached ${Object.keys(cachedCombosToScores)?.length} pulse tag combos to scores`);
  };

  const refreshTags = async (transaction) => {
    cachedPulseTags = await models.PulseTag.findAll({
      where: { isActive: true, deletedAt: null },
      order: [['name', SortDirection.Ascending]],
      transaction,
    });
    logger.info(`Cached ${cachedPulseTags.length} pulse tags`);
  };

  await Promise.all([refreshComboData(transaction), refreshTags(transaction)]);
  cachedTagDataLastUpdated = moment();
}

async function getCombosToScores({ transaction = null } = {}) {
  if (_.isEmpty(cachedCombosToScores)) {
    await cacheTagQuantData({ transaction });
  }
  return cachedCombosToScores;
}

async function listAllPulseTags({ transaction = null }) {
  if (_.isEmpty(cachedPulseTags)) {
    await cacheTagQuantData({ transaction });
  }
  return _.cloneDeep(cachedPulseTags);
}

async function _getTagQuantData({ transaction = null }) {
  const query = `
  select 
    pt.id as tag_id, 
    pt.type as tag_type, 
    ptt.pulse_id as pulse_id, 
    ((((aisr.quant->'scores')::jsonb)->0)::jsonb)->>'name' as name1, 
    ((((aisr.quant->'scores')::jsonb)->0)::jsonb)->'score' as score1,
    ((((aisr.quant->'scores')::jsonb)->0)::jsonb)->'rawScore' as raw_score1, 
    ((((aisr.quant->'scores')::jsonb)->1)::jsonb)->>'name' as name2, 
    ((((aisr.quant->'scores')::jsonb)->1)::jsonb)->'score' as score2,
    ((((aisr.quant->'scores')::jsonb)->1)::jsonb)->'rawScore' as raw_score2, 
    ((((aisr.quant->'scores')::jsonb)->2)::jsonb)->>'name' as name3, 
    ((((aisr.quant->'scores')::jsonb)->2)::jsonb)->'score' as score3,
    ((((aisr.quant->'scores')::jsonb)->2)::jsonb)->'rawScore' as raw_score3, 
    aisr.quant->'average' as top_level_score, 
    aisr.quant->'rawScoreAverage' as top_level_raw, 
    aisr.created_at as created_at 
  from wevo.pulse_to_tag ptt
  join wevo.pulse_tag pt on pt.id = ptt.tag_id 
  join wevo.automated_insight_session_result aisr on aisr.automated_insight_session_id = ptt.pulse_id 
  where 
    ptt.deleted_at is null
    and aisr.quant <> '{}'
    and aisr.segment_id is null
    and pt.is_active is true`;
  const results = await sequelize.query(query, { type: QueryTypes.SELECT, transaction });

  const tagQuantData = results.map((result) => {
    const {
      tag_id: tagId,
      tag_type: tagType,
      pulse_id: pulseId,
      name1,
      score1,
      raw_score1: rawScore1,
      name2,
      score2,
      raw_score2: rawScore2,
      name3,
      score3,
      raw_score3: rawScore3,
      top_level_score: topLevelScore,
      top_level_raw: topLevelRaw,
      created_at: createdAt,
    } = result;

    return {
      tagId,
      tagType,
      pulseId,
      scores: {
        [name1]: { score: Number(score1), rawScore: Number(rawScore1) },
        [name2]: { score: Number(score2), rawScore: Number(rawScore2) },
        [name3]: { score: Number(score3), rawScore: Number(rawScore3) },
        topLevel: { score: Number(topLevelScore), rawScore: Number(topLevelRaw) },
      },
      createdAt,
    };
  });

  return tagQuantData;
}

